const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;padding:10px;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden;min-width:0;min-height:0}\n.card[data-size=\"3x3\"]{padding:8px;font-size:11px}\n.card *{box-sizing:border-box}\n.col{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.fill{flex:1;min-height:0;min-width:0;overflow:auto}\n.dual{flex:1;min-height:0;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:10px}\n.dual>.pane{border-left:1px solid var(--line);padding-left:10px}\n.top{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.ttl{margin:0;font-size:14px;font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.btn{font:inherit;font-size:11px;color:var(--ink);background:var(--button-paper,var(--panel-paper));border:1px solid var(--line);border-radius:8px;padding:4px 6px;min-height:28px;cursor:pointer;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.add{flex:none}\n.btn.back{flex:none;padding:4px 8px}\n.bar{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}\n.list,.scroll{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:5px;padding-right:2px}\n.row{display:flex;flex-direction:column;gap:2px;flex:none;width:100%;min-width:0;text-align:left;font:inherit;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px;padding:6px 8px;cursor:pointer}\n.row.on{border-color:var(--accent);box-shadow:inset 3px 0 0 var(--accent)}\n.r1{display:flex;align-items:center;gap:6px;min-width:0}\n.nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.nm.big{font-size:13px}\n.r2{display:block;color:var(--muted);font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.r2.peek{color:var(--ink)}\n.due{color:var(--accent)}\n.chip{flex:none;font-size:10px;line-height:1.5;padding:0 6px;border-radius:999px;background:var(--soft);color:var(--ink);border:1px solid var(--line);white-space:nowrap}\n.chip.chg{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.chip.paused,.chip.none{color:var(--muted);border-style:dashed}\n.pausedline,.hint{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.pausedline{padding:4px 8px;border:1px dashed var(--line);border-radius:8px}\n.hint.foot{padding:4px 2px;font-size:10px}\n.empty{display:flex;flex-direction:column;gap:6px;align-items:flex-start;padding:4px 2px}\n.empty p{margin:0}\n.empty .big{font-size:13px;font-weight:700}\n.notice{display:flex;gap:6px;align-items:flex-start;flex:none;padding:6px 8px;border:1px solid var(--accent);background:var(--soft);border-radius:8px;font-size:11px}\n.notice .nt{flex:1;min-width:0;overflow-wrap:anywhere}\n.notice .x{flex:none;font:inherit;font-size:14px;line-height:1;width:22px;height:22px;color:var(--ink);background:transparent;border:0;cursor:pointer}\n.dhead{display:flex;align-items:center;gap:6px;min-width:0}\n.acts{display:flex;flex-direction:column;gap:4px}\n.a2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px}\n.a3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}\n.confirm{display:flex;flex-direction:column;gap:4px;font-size:11px;padding:4px 6px;border:1px dashed var(--accent);border-radius:8px}\n.info,.logbody{display:flex;flex-direction:column;gap:3px;min-width:0}\n.logbody{padding:2px}\n.kv{display:flex;gap:6px;min-width:0;align-items:flex-start}\n.kv .k{flex:none;width:2.6em;color:var(--muted)}\n.kv .v{flex:1;min-width:0;overflow-wrap:anywhere}\n.lnk{color:var(--accent);text-decoration:underline;overflow-wrap:anywhere;min-width:0}\n.sec{margin:6px 0 0;font-size:12px;font-weight:700}\n.meta{color:var(--muted);font-size:10px}\n.cmp{display:flex;flex-direction:column;gap:3px;min-width:0;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--soft)}\n.cmp .sec{margin:0}\n.grp{display:flex;flex-direction:column;gap:2px;min-width:0}\n.gt{font-weight:600;overflow-wrap:anywhere}\n.gt.mut{color:var(--muted);font-weight:400}\n.items{margin:0;padding:0 0 0 14px;display:flex;flex-direction:column;gap:2px;min-width:0}\n.items li{overflow-wrap:anywhere}\n.items.add{list-style:\"\uff0b \"}\n.items.rem{list-style:\"\uff0d \";color:var(--muted);text-decoration:line-through}\n";
var FREQ=[
  {value:'hourly',label:'每小时',ms:3600000},
  {value:'daily',label:'每天',ms:86400000},
  {value:'weekly',label:'每周',ms:604800000},
  {value:'monthly',label:'每月',ms:2592000000}
];
function freqOf(v){return FREQ.find(function(f){return f.value===v;})||FREQ[1];}
function pad2(n){return n<10?'0'+n:''+n;}
function fmtTime(t){var d=new Date(t);return pad2(d.getMonth()+1)+'-'+pad2(d.getDate())+' '+pad2(d.getHours())+':'+pad2(d.getMinutes());}
function normLine(x){return String(x==null?'':x).replace(/\s+/g,' ').trim();}
function parseItems(text){
  var seen=[];var out=[];
  String(text||'').split(/\n/).forEach(function(l){
    var n=normLine(l);var k=n.toLowerCase();
    if(n&&seen.indexOf(k)<0){seen.push(k);out.push(n);}
  });
  return out;
}
function diffItems(prev,cur){
  if(!prev)return {first:true,added:[],removed:[],same:cur.length};
  var pk=prev.map(function(x){return x.toLowerCase();});
  var ck=cur.map(function(x){return x.toLowerCase();});
  var added=cur.filter(function(x){return pk.indexOf(x.toLowerCase())<0;});
  var removed=prev.filter(function(x){return ck.indexOf(x.toLowerCase())<0;});
  return {first:false,added:added,removed:removed,same:cur.length-added.length};
}
function hostOf(u){return String(u||'').replace(/^https?:\/\//i,'').split(/[\/?#]/)[0];}
function okUrl(u){return /^https?:\/\/[^\s\/$.?#][^\s]*$/i.test(u);}
function sameUrl(a,b){return String(a).toLowerCase().replace(/\/+$/,'')===String(b).toLowerCase().replace(/\/+$/,'');}
function initialize(s){
  var b=s||{};
  if(Array.isArray(b.sources)&&Array.isArray(b.logs))return s;
  return Object.assign({},b,{
    sources:Array.isArray(b.sources)?b.sources:[],
    logs:Array.isArray(b.logs)?b.logs:[],
    paused:!!b.paused
  });
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,size,uid,editor,panel}=ctx;
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat(2).filter(k=>k!==null&&k!==undefined&&k!==false));
  const sources=Array.isArray(state.sources)?state.sources:[];
  const logs=Array.isArray(state.logs)?state.logs:[];
  const allPaused=!!state.paused;
  const dual=size==='6x3'||size==='6x6';
  const roomy=size==='3x6'||size==='6x6';
  const srcById=id=>sources.find(x=>x.id===id)||null;
  const logsOf=id=>logs.filter(x=>x.sourceId===id);
  const lastOf=id=>{const l=logsOf(id);return l.length?l[l.length-1]:null;};
  const afterView=()=>dual?'home':(srcById(ui.sel)?'detail':'home');
  const go=(view,extra)=>{Object.assign(ui,extra||{});ui.view=view;redraw();};
  const note=(text,kind)=>{ui.notice=text?{text:text,kind:kind||'info'}:null;redraw();};
  const save=(fn,after)=>update(fn).then(()=>{if(after)after();}).catch(e=>note('保存失败：'+((e&&e.message)||'请稍后重试'),'err'));
  const NOT_WIRED='立即检查暂未接入：平台目前不能读取官网网页，也没有后台定时，所以这次没有产生任何检查结果，也没有写入记录。链接、关心的内容和频率都已保存。可先打开链接查看，再点「记录结果」手动登记，卡片会与上次记录对比。';

  function summary(l){
    if(l.first)return '首次基线 '+l.items.length+' 条';
    if(!l.added.length&&!l.removed.length)return '无变化';
    return '新增'+l.added.length+' 移除'+l.removed.length;
  }
  function logChip(l){
    if(l.first)return h('span',{class:'chip base'},'基线');
    if(l.added.length||l.removed.length)return h('span',{class:'chip chg'},'有更新');
    return h('span',{class:'chip same'},'无变化');
  }
  function statusOf(src){
    const last=lastOf(src.id);
    const fl=freqOf(src.freq);
    const off=allPaused||!!src.paused;
    if(!last)return {k:off?'paused':'none',t:off?'已暂停':'未记录',sub:fl.label+'检查 · 暂无记录',due:!off,peek:''};
    const due=!off&&(Date.now()-last.at>=fl.ms);
    let k,t;
    if(off){k='paused';t='已暂停';}
    else if(last.first){k='base';t='基线';}
    else if(last.added.length||last.removed.length){k='chg';t='有更新';}
    else{k='same';t='无变化';}
    return {k:k,t:t,sub:fmtTime(last.at)+' · '+summary(last),due:due,peek:last.added.length?'＋ '+last.added[0]:''};
  }
  function linkNode(u){
    if(!u)return h('span',{class:'v'},'—');
    return h('a',{class:'lnk',href:u,target:'_blank',rel:'noopener noreferrer'},u);
  }
  function linkify(text){
    return String(text).split(/(https?:\/\/[^\s]+)/).map((p,i)=>i%2?linkNode(p):p);
  }
  function itemList(items,cls){
    return h('ul',{class:'items '+(cls||'')},items.map(t=>h('li',null,linkify(t))));
  }
  function diffLists(l){
    if(l.first)return h('div',{class:'grp'},h('div',{class:'gt'},'首次记录，作为后续对比的基线'),itemList(l.items));
    if(!l.added.length&&!l.removed.length)return h('div',{class:'grp'},h('div',{class:'gt'},'与上次相比无变化（共 '+l.items.length+' 条要点）'));
    return h('div',{class:'grp'},
      l.added.length?[h('div',{class:'gt add'},'＋ 新增 '+l.added.length+' 条'),itemList(l.added,'add')]:null,
      l.removed.length?[h('div',{class:'gt rem'},'－ 移除 '+l.removed.length+' 条'),itemList(l.removed,'rem')]:null,
      l.same?h('div',{class:'gt mut'},'其余 '+l.same+' 条不变'):null);
  }
  function noticeNode(){
    if(!ui.notice)return null;
    return h('div',{class:'notice '+ui.notice.kind,role:'status'},
      h('span',{class:'nt'},h('b',null,ui.notice.kind==='err'?'出错 ':'说明 '),ui.notice.text),
      h('button',{type:'button',class:'x','aria-label':'关闭提示',onclick:()=>{ui.notice=null;redraw();}},'×'));
  }
  function kv(k,v){return h('div',{class:'kv'},h('span',{class:'k'},k),h('span',{class:'v'},v));}

  function row(src,curId){
    const st=statusOf(src);
    const on=curId===src.id;
    return h('button',{type:'button',class:'row'+(on?' on':''),onclick:()=>go(dual?'home':'detail',{sel:src.id,confirmDel:null,notice:null})},
      h('span',{class:'r1'},h('span',{class:'nm'},src.name),h('span',{class:'chip '+st.k},st.t)),
      h('span',{class:'r2'},st.due?h('b',{class:'due'},'该检查了 · '):null,st.sub),
      roomy&&st.peek?h('span',{class:'r2 peek'},st.peek):null);
  }
  function logRow(l,showSrc){
    const gone=showSrc&&!srcById(l.sourceId);
    return h('button',{type:'button',class:'row',onclick:()=>go('log',{logId:l.id,logFrom:ui.view})},
      h('span',{class:'r1'},h('span',{class:'nm'},showSrc?l.srcName:fmtTime(l.at)),logChip(l)),
      h('span',{class:'r2'},(showSrc?fmtTime(l.at)+' · ':'')+summary(l)+(gone?' · 来源已移除':'')));
  }


  function checkNow(src){
    if(allPaused)return note('已暂停全部跟踪，请先点「恢复全部」。');
    if(src&&src.paused)return note('「'+src.name+'」已暂停，恢复后才能检查。');
    if(!src){
      if(!sources.length)return note('还没有添加官网来源，先点「＋ 添加」。');
      if(sources.every(x=>x.paused))return note('所有来源都已暂停。');
    }
    note(NOT_WIRED,'warn');
  }
  function openRecord(src){
    if(allPaused)return note('已暂停全部跟踪，恢复后才能记录。');
    if(src.paused)return note('「'+src.name+'」已暂停，恢复后才能记录。');
    const last=lastOf(src.id);
    go('record',{sel:src.id,draft:{items:last?last.items.join('\n'):'',link:'',note:''},notice:null});
  }
  const openAdd=()=>go('edit',{editId:null,sel:dual?ui.sel:null,draft:{name:'',url:'',focus:'',freq:'daily'},notice:null});
  const openEdit=src=>go('edit',{editId:src.id,sel:src.id,draft:{name:src.name,url:src.url,focus:src.focus||'',freq:src.freq||'daily'},notice:null});
  const toggleAll=()=>save(s=>Object.assign({},s,{paused:!s.paused}));
  const toggleSrc=src=>save(s=>Object.assign({},s,{sources:(s.sources||[]).map(x=>x.id===src.id?Object.assign({},x,{paused:!x.paused}):x)}));
  const removeSrc=src=>save(
    s=>Object.assign({},s,{sources:(s.sources||[]).filter(x=>x.id!==src.id)}),
    ()=>go('home',{confirmDel:null,sel:null,notice:null}));

  function actionsNode(src){
    const del=ui.confirmDel===src.id;
    return h('div',{class:'acts'},
      h('div',{class:'a2'},
        h('button',{type:'button',class:'btn pri',onclick:()=>checkNow(src)},'立即检查'),
        h('button',{type:'button',class:'btn',onclick:()=>openRecord(src)},'记录结果')),
      del?h('div',{class:'confirm'},
        h('span',null,'移除后不再跟踪；已有的检查记录仍保留在历史里。'),
        h('div',{class:'a2'},
          h('button',{type:'button',class:'btn',onclick:()=>removeSrc(src)},'确认移除'),
          h('button',{type:'button',class:'btn',onclick:()=>go(ui.view,{confirmDel:null})},'取消')))
      :h('div',{class:'a3'},
        h('button',{type:'button',class:'btn',onclick:()=>toggleSrc(src)},src.paused?'恢复':'暂停'),
        h('button',{type:'button',class:'btn',onclick:()=>openEdit(src)},'编辑'),
        h('button',{type:'button',class:'btn',onclick:()=>go(ui.view,{confirmDel:src.id})},'移除')));
  }
  function compareBlock(src){
    const ls=logsOf(src.id);
    const l=ls.length?ls[ls.length-1]:null;
    if(!l)return h('div',{class:'hint'},'还没有检查记录。打开官网链接查看后点「记录结果」登记要点，之后每次都会和上一次对比，列出新增与移除。');
    return h('section',{class:'cmp'},
      h('h4',{class:'sec'},l.first?'最新：首次记录':'最新：较上次的变化'),
      h('div',{class:'meta'},(l.prevAt?fmtTime(l.prevAt)+' → ':'')+fmtTime(l.at)),
      diffLists(l),
      kv('出处',linkNode(l.link||l.srcUrl)),
      l.note?kv('备注',l.note):null);
  }
  function scrollNode(src,withNotice){
    const ls=logsOf(src.id).slice().reverse();
    const off=allPaused||src.paused;
    return h('div',{class:'scroll'},
      withNotice?noticeNode():null,
      h('div',{class:'info'},
        kv('官网',linkNode(src.url)),
        kv('关心',src.focus||'未填写'),
        kv('频率',freqOf(src.freq).label+(off?'（已暂停）':''))),
      compareBlock(src),
      h('h4',{class:'sec'},'检查记录（'+ls.length+'）'),
      ls.length?ls.map(l=>logRow(l,false)):h('div',{class:'hint'},'暂无记录。'));
  }
  function detailHead(src,withBack){
    const st=statusOf(src);
    return h('div',{class:'dhead'},
      withBack?h('button',{type:'button',class:'btn back','aria-label':'返回列表',onclick:()=>go('home',{confirmDel:null})},'‹ 返回'):null,
      h('span',{class:'nm big'},src.name),
      h('span',{class:'chip '+st.k},st.t));
  }
  function detailView(){
    const src=srcById(ui.sel);
    return h('div',{class:'col pane'},detailHead(src,true),actionsNode(src),scrollNode(src,true));
  }
  function historyView(){
    const ls=logs.slice().reverse();
    return h('div',{class:'col pane'},
      h('div',{class:'dhead'},
        h('button',{type:'button',class:'btn back','aria-label':'返回',onclick:()=>go('home',{})},'‹ 返回'),
        h('span',{class:'nm big'},'检查记录（'+ls.length+'）')),
      h('div',{class:'scroll'},
        ls.length?ls.map(l=>logRow(l,true)):h('div',{class:'hint'},'还没有检查记录。在来源里点「记录结果」登记后会出现在这里，并一直保留。')));
  }
  function logView(){
    const l=logs.find(x=>x.id===ui.logId);
    const body=h('div',{class:'logbody'},
      kv('来源',l.srcName+(srcById(l.sourceId)?'':'（已移除）')),
      kv('时间',fmtTime(l.at)),
      kv('对比',l.prevAt?'与 '+fmtTime(l.prevAt)+' 的记录对比':'首次记录，无对比对象'),
      kv('出处',linkNode(l.link||l.srcUrl)),
      l.note?kv('备注',l.note):null,
      diffLists(l.first?Object.assign({},l,{items:l.items}):l),
      l.first?null:h('h4',{class:'sec'},'本次全部要点（'+l.items.length+'）'),
      l.first?null:itemList(l.items));
    return h('div',{class:'fill'},panel({title:'检查记录',body:body,onBack:()=>go(ui.logFrom||'home',{})}));
  }


  function sourceForm(){
    const editing=ui.editId?srcById(ui.editId):null;
    return h('div',{class:'fill'},editor({
      title:editing?'编辑来源':'添加官网来源',
      draft:ui.draft,
      submitLabel:editing?'保存修改':'添加',
      fields:[
        {key:'url',label:'官网链接',required:true,placeholder:'https://example.com/changelog'},
        {key:'name',label:'名称（留空则用网址域名）',placeholder:'如：某产品官网'},
        {key:'focus',label:'关心的内容',type:'textarea',placeholder:'如：新功能、价格调整、版本号'},
        {key:'freq',label:'检查频率（用于到期提醒）',type:'select',options:FREQ.map(f=>({value:f.value,label:f.label}))}
      ],
      onBack:()=>go(afterView(),{draft:null,editId:null}),
      onSave:v=>{
        const url=normLine(v.url);
        if(!okUrl(url))return '请填写以 http:// 或 https:// 开头的官网链接';
        if(sources.some(x=>x.id!==ui.editId&&sameUrl(x.url,url)))return '这个链接已经在跟踪列表里了';
        const name=normLine(v.name)||hostOf(url);
        const focus=String(v.focus||'').trim();
        const freq=freqOf(v.freq).value;
        const id=editing?editing.id:uid();
        const next=Object.assign({},ui,{view:dual?'home':'detail',sel:id,draft:null,editId:null,notice:null,confirmDel:null});
        return commit(s=>{
          const list=s.sources||[];
          if(editing)return Object.assign({},s,{sources:list.map(x=>x.id===id?Object.assign({},x,{name:name,url:url,focus:focus,freq:freq}):x)});
          return Object.assign({},s,{sources:list.concat([{id:id,name:name,url:url,focus:focus,freq:freq,paused:false,createdAt:Date.now()}])});
        },next);
      }
    }));
  }
  function recordForm(){
    const src=srcById(ui.sel);
    return h('div',{class:'fill'},editor({
      title:'记录结果 · '+src.name,
      draft:ui.draft,
      submitLabel:'保存并对比上次',
      fields:[
        {key:'items',label:'你在官网看到的要点（手动登记，每行一条，行尾可附该条出处链接）',type:'textarea',required:true,placeholder:'如：v3.2 新增夜间模式 https://example.com/news/3-2'},
        {key:'link',label:'本次出处链接（留空则用官网链接）',placeholder:'https://…'},
        {key:'note',label:'备注（可选）',type:'textarea'}
      ],
      onBack:()=>go(afterView(),{draft:null}),
      onSave:v=>{
        const items=parseItems(v.items);
        if(!items.length)return '请至少填写一条要点';
